<main style="padding:28px"><div style="display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:22px"><div><h1 style="margin:0">Historial de mensajes</h1><p style="color:#64748b">Registro de conversaciones, agentes, automatizaciones y campañas.</p></div></div>
<div style="display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:10px;margin-bottom:18px"><input wire:model.live.debounce.300ms="search" placeholder="Buscar teléfono, contacto o mensaje" style="padding:11px;border:1px solid #cbd5e1;border-radius:8px"><select wire:model.live="direction" style="padding:11px;border:1px solid #cbd5e1;border-radius:8px"><option value="all">Todas las direcciones</option><option value="inbound">Entrantes</option><option value="outbound">Salientes</option></select><select wire:model.live="source" style="padding:11px;border:1px solid #cbd5e1;border-radius:8px"><option value="all">Todos los orígenes</option><option value="manual">Perfil / agente</option><option value="automatic">Respuesta automática</option><option value="ai_agent">Agente IA</option><option value="campaign">Campaña</option><option value="webhook">Cliente</option></select><select wire:model.live="status" style="padding:11px;border:1px solid #cbd5e1;border-radius:8px"><option value="all">Todos los estados</option><option value="sent">Enviado</option><option value="delivered">Entregado</option><option value="read">Leído</option><option value="failed">Fallido</option></select></div>
<div style="overflow:auto;background:white;border:1px solid #e2e8f0;border-radius:12px"><table style="width:100%;border-collapse:collapse"><thead><tr style="text-align:left;background:#f8fafc"><th style="padding:13px">Fecha</th><th style="padding:13px">Contacto</th><th style="padding:13px">Dirección</th><th style="padding:13px">Origen</th><th style="padding:13px">Mensaje</th><th style="padding:13px">Estado</th></tr></thead><tbody>@forelse($messages as $message)<tr style="border-top:1px solid #e2e8f0"><td style="padding:13px;white-space:nowrap">{{ optional($message->received_at)->format('d/m/Y H:i') }}</td><td style="padding:13px">{{ $message->contact_name ?: '—' }}<br><small>{{ $message->phone }}</small></td><td style="padding:13px">{{ $message->direction === 'inbound' ? 'Entrante' : 'Saliente' }}</td><td style="padding:13px">{{ ['manual'=>'Perfil / agente','automatic'=>'Automática','ai_agent'=>'Agente IA','campaign'=>'Campaña','webhook'=>'Cliente'][$message->source] ?? $message->source }}</td><td style="padding:13px;max-width:420px;white-space:pre-wrap">{{ $message->message }}</td><td style="padding:13px">{{ ucfirst($message->status) }}</td></tr>@empty<tr><td colspan="6" style="padding:30px;text-align:center">No hay mensajes registrados.</td></tr>@endforelse</tbody></table></div><div style="margin-top:16px">{{ $messages->links() }}</div></main>
